ROOT=Path('/tmp/cfc-phase3-forward-detection')
class Packet:
 def __init__(self,object_type,object_id):
  self.doc={'request_id':'FORWARD-'+object_id,'object_id':object_id,'object_type':object_type,'as_of':'2026-10-04','knowledge_cutoff':'2026-10-04','workflow':{'context':{'institution_id':'DEIDENTIFIED-REGIONAL-BANK','legal_entity_id':'BANK-LEGAL-ENTITY-01','capacity':'internal-control-review','represented_party':'institution','object_id':object_id,'object_type':object_type,'jurisdiction':'US-bank-supplied-profile','line_of_business':'retail-deposits-and-wire-operations','purpose':'scope-specific-forward-evaluation'},'as_of':'2026-10-04','role':'operational_qa','classification':'compliance_confidential','audience':'institution-testing-owner','allowed_audiences':['institution-testing-owner'],'sources':[],'unresolved_issues':[]},'sources':[],'data':{}}
  self.sources={}
 def c(self,v,source='WORKPAPERS'):
  ref='FORWARD-'+source
  if ref not in self.sources:
   s={'source_ref':ref,'version':'packet-review-2026-10-04','publication_date':'2026-10-03','received_at':'2026-10-04','classification':'compliance_confidential','permitted_audiences':['institution-testing-owner'],'facts':[]}
   self.sources[ref]=s;self.doc['sources'].append(s);self.doc['workflow']['sources'].append({'source_ref':ref,'version':s['version']})
  facts=self.sources[ref]['facts'];fid=ref+'-FACT-'+str(len(facts)+1);facts.append({'fact_id':fid,'value':copy.deepcopy(v),'excerpt':'Original de-identified synthetic forward packet: '+json.dumps(v)})
  return {'value':v,'source_refs':[ref],'fact_ids':[fid]}
 def row(self,v,ids=None,source='WORKPAPERS'):
  return {**(ids or {}),**{k:self.c(val,source) for k,val in v.items()}}

def mutate(doc,claim,value):
 claim['value']=copy.deepcopy(value)
 for s in doc['sources']:
  for f in s['facts']:
   if f['fact_id'] in claim['fact_ids']:f['value']=copy.deepcopy(value);f['excerpt']='Changed de-identified synthetic forward packet: '+json.dumps(value)

